lesson.solution:
def __check_error(error_type, expression):
    try:
        eval(expression)
    except error_type:
        return True
    return False

def make_label(title, *, uppercase=False, **extras):
    for key in extras:
        if key != "prefix":
            raise ValueError("Unknown option")
    text = title.upper() if uppercase else title
    return extras.get("prefix", "") + text
